# Hypothesis 1: When a row has 2s, flip them to 0s (complement)
# This converts 0s to 2s in rows that had patterns
def complement_in_pattern_rows(g, rows_with_pattern):
    # Find rows that had any 2s
    rows_with_pattern = set()
    for r in range(len(g)):
        for c in range(len(g[r])):
            if g[r][c] == 2:
                rows_with_pattern.add(r)
    # In those rows, flip 2s to 0s
    result = [row[:] for row in g]
    for r in rows_with_pattern:
        for c in range(len(result[r])):
            if result[r][c] == 2:
                result[r][c] = 0
    return result

# Hypothesis 2: Shift the pattern up by 4 rows
def shift_up(g, shift=4):
    result = [[0]*len(g[0]) for _ in range(len(g))]
    for r in range(len(g)):
        for c in range(len(g[r])):
            if g[r][c] == 2:
                nr = max(0, r - shift)
                result[nr][c] = 2
    return result

